CREATE FUNCTION `c4j_GetControlValue`(
	XNAME VARCHAR ( 50 )) RETURNS varchar(50) CHARSET utf8mb4
    READS SQL DATA
BEGIN
	DECLARE
		result VARCHAR ( 50 ) CHARACTER 
		SET utf8mb4;

	SET result = ( SELECT key_value FROM SYS_CONTROL WHERE system_key = XNAME );
	RETURN result;

END

CREATE FUNCTION `c4j_GetDay`( XDATE datetime ) RETURNS varchar(2) CHARSET utf8mb4
    NO SQL
    DETERMINISTIC
BEGIN
	DECLARE
		result VARCHAR ( 2 ) CHARACTER 
		SET utf8mb4;
	DECLARE
		dom INT;

	SET dom = DAYOFMONTH( XDATE );

	SET result = RIGHT (
		CONCAT(
			'0',
		CONVERT ( dom, CHAR )),
		2 
	);
	RETURN result;

END

CREATE FUNCTION `c4j_GetFinalBatchNumber`(
	XPRODUCTION_DATE datetime,
	XOVERRIDE_BATCH VARCHAR ( 1 ),
	XOVERRIDE_BATCH_NUMBER VARCHAR ( 40 ),
	XBATCH_OPTIONAL VARCHAR ( 40 ),
	XPROCESS_ORDER VARCHAR ( 40 )) RETURNS varchar(100) CHARSET utf8mb4
    NO SQL
BEGIN
	DECLARE
		result VARCHAR ( 100 ) CHARACTER 
		SET utf8mb4;
	DECLARE
		batchformat VARCHAR ( 100 ) CHARACTER 
		SET utf8mb4;
	IF
		XOVERRIDE_BATCH = 'Y' THEN

			SET result = XOVERRIDE_BATCH_NUMBER;

	END IF;
	IF
		XOVERRIDE_BATCH = 'N' THEN

			SET batchformat = c4j_GetControlValue ( 'BATCH FORMAT' );

		SET result = batchformat;

		SET result = REPLACE (
			result,
			'{PLANT}',
		c4j_GetPlant ());

		SET result = REPLACE ( result, '{PROCESS_ORDER}', XPROCESS_ORDER );

		SET result = REPLACE (
			result,
			'{YEAR4}',
		c4j_GetYear ( XPRODUCTION_DATE, 4 ));

		SET result = REPLACE (
			result,
			'{YEAR2}',
		c4j_GetYear ( XPRODUCTION_DATE, 2 ));

		SET result = REPLACE (
			result,
			'{YEAR1}',
		c4j_GetYear ( XPRODUCTION_DATE, 1 ));

		SET result = REPLACE (
			result,
			'{MONTH}',
		c4j_GetMonth ( XPRODUCTION_DATE ));

		SET result = REPLACE (
			result,
			'{DAY}',
		c4j_GetDay ( XPRODUCTION_DATE ));

		SET result = REPLACE (
			result,
			'{JULIAN_DAY}',
		c4j_GetJulian ( XPRODUCTION_DATE, 1 ));

		SET result = REPLACE (
			result,
			'{JULIAN0_DAY}',
		c4j_GetJulian ( XPRODUCTION_DATE, 0 ));

		SET result = REPLACE (
			result,
			'{JULIAN1_DAY}',
		c4j_GetJulian ( XPRODUCTION_DATE, 1 ));

	END IF;

	SET result = CONCAT( result, XBATCH_OPTIONAL );
	RETURN result;

END

CREATE FUNCTION `c4j_GetFullPalletQuantity`(
	XPROCESS_ORDER VARCHAR ( 40 )) RETURNS decimal(22,3)
    READS SQL DATA
BEGIN
	DECLARE
		result DECIMAL ( 22, 3 );
	DECLARE
		xmaterial VARCHAR ( 40 ) CHARACTER 
		SET utf8mb4;
	DECLARE
		xpal_uom VARCHAR ( 3 ) CHARACTER 
		SET utf8mb4;
	DECLARE
		xpal_numerator DECIMAL ( 22, 3 );
	DECLARE
		xpal_denominator DECIMAL ( 22, 3 );
	DECLARE
		xrequired_uom VARCHAR ( 3 ) CHARACTER 
		SET utf8mb4;
	DECLARE
		xrequired_denominator DECIMAL ( 22, 3 );
	DECLARE
		xrequired_numerator DECIMAL ( 22, 3 );

	SET xpal_uom = c4j_GetControlValue ( 'UOM FULL PALLET QTY' );

	SET xrequired_uom = ( SELECT REQUIRED_UOM FROM APP_PROCESS_ORDER WHERE PROCESS_ORDER = XPROCESS_ORDER );

	SET xmaterial = ( SELECT MATERIAL FROM APP_PROCESS_ORDER WHERE PROCESS_ORDER = XPROCESS_ORDER );

	SET xrequired_denominator = (
		SELECT
			DENOMINATOR 
		FROM
			APP_MATERIAL_UOM 
		WHERE
			MATERIAL = xmaterial 
			AND UOM = xrequired_uom 
		);

	SET xrequired_numerator = (
		SELECT
			NUMERATOR 
		FROM
			APP_MATERIAL_UOM 
		WHERE
			MATERIAL = xmaterial 
			AND UOM = xrequired_uom 
		);

	SET xpal_denominator = (
		SELECT
			DENOMINATOR 
		FROM
			APP_MATERIAL_UOM 
		WHERE
			MATERIAL = xmaterial 
			AND UOM = xpal_uom 
		);

	SET xpal_numerator = (
		SELECT
			NUMERATOR 
		FROM
			APP_MATERIAL_UOM 
		WHERE
			MATERIAL = xmaterial 
			AND UOM = xpal_uom 
		);

	SET result = ( xpal_numerator / xpal_denominator ) * ( xrequired_denominator / xrequired_numerator );
	RETURN result;

END

CREATE FUNCTION `c4j_GetJulian`( XDATE datetime, XOFFSET INT ) RETURNS varchar(6) CHARSET utf8mb4
    NO SQL
    DETERMINISTIC
BEGIN
	DECLARE
		result VARCHAR ( 6 ) CHARACTER 
		SET utf8mb4;
	DECLARE
		dayofyear INT;

	SET dayofyear = DAYOFYEAR( XDATE )- 1+XOFFSET;

	SET result = RIGHT (
		CONCAT(
			'000',
		CONVERT ( dayofyear, CHAR )),
		3 
	);
	RETURN result;

END

CREATE FUNCTION `c4j_GetLayers`(
	XPROCESS_ORDER VARCHAR ( 20 )) RETURNS int
    READS SQL DATA
BEGIN
	DECLARE
		result INT;
	DECLARE
		xlayers_uom VARCHAR ( 3 ) CHARACTER 
		SET utf8mb4;
	DECLARE
		xpallet_uom VARCHAR ( 3 ) CHARACTER 
		SET utf8mb4;
	DECLARE
		xbase_quantity DECIMAL ( 22, 3 );
	DECLARE
		xmaterial VARCHAR ( 20 ) CHARACTER 
		SET utf8mb4;
	DECLARE
		xproduction_uom VARCHAR ( 3 ) CHARACTER 
		SET utf8mb4;
	DECLARE
		xproduction_quantity DECIMAL ( 22, 3 );

	SET xproduction_quantity = c4j_GetFullPalletQuantity ( XPROCESS_ORDER );

	SET xmaterial = ( SELECT MATERIAL FROM APP_PROCESS_ORDER WHERE PROCESS_ORDER = XPROCESS_ORDER );

	SET xproduction_uom = ( SELECT REQUIRED_UOM FROM APP_PROCESS_ORDER WHERE PROCESS_ORDER = XPROCESS_ORDER );

	SET xbase_quantity = c4j_GetBaseQuantity ( XMATERIAL, XPRODUCTION_QUANTITY, XPRODUCTION_UOM );

	SET xlayers_uom = c4j_GetControlValue ( 'UOM BASE QTY PER LAYER' );

	SET result = (
		SELECT
			CEILING( xbase_quantity / NUMERATOR * DENOMINATOR ) 
		FROM
			APP_MATERIAL_UOM 
		WHERE
			MATERIAL = xmaterial 
			AND UOM = xlayers_uom 
		);

	SET result = COALESCE ( result, 1 );
	IF
		result = 0 THEN

			SET result = 1;

	END IF;
	RETURN result;

END

CREATE FUNCTION `c4j_GetMonth`( XDATE datetime ) RETURNS varchar(2) CHARSET utf8mb4
    NO SQL
    DETERMINISTIC
BEGIN
	DECLARE
		result VARCHAR ( 6 ) CHARACTER 
		SET utf8mb4;
	DECLARE
		moy INT;

	SET moy = MONTH ( XDATE );

	SET result = RIGHT (
		CONCAT(
			'0',
		CONVERT ( moy, CHAR )),
		2 
	);
	RETURN result;

END

CREATE FUNCTION `c4j_GetPlant` () RETURNS VARCHAR ( 10 ) CHARSET utf8mb4 READS SQL DATA BEGIN
	DECLARE
		result VARCHAR ( 10 ) CHARACTER 
		SET utf8mb4;

	SET result = c4j_GetControlValue ( 'PLANT' );
	RETURN result;

END

CREATE FUNCTION `c4j_GetYear`( XDATE datetime, XSIZE INT ) RETURNS int NO SQL DETERMINISTIC BEGIN DECLARE result VARCHAR ( 4 ) CHARACTER SET utf8mb4;
SET result = RIGHT ( CAST( YEAR ( XDATE ) AS CHAR ( 4 )), XSIZE ); RETURN result;
END

CREATE FUNCTION `GetFullPalletLayers` (xmaterial VARCHAR (20), xproduction_uom VARCHAR (3)) RETURNS INT READS SQL DATA
BEGIN
	DECLARE	Xlayers INT;
	DECLARE	xpallet_uom VARCHAR (3) CHARACTER	SET utf8mb4;
	DECLARE	xbase_uom VARCHAR (3) CHARACTER	SET utf8mb4;
	DECLARE	xfull_pallet_quantity DECIMAL (22, 3);

	SET xpallet_uom = 'PAL';
	SET xbase_uom = (SELECT BASE_UOM FROM APP_MATERIAL WHERE MATERIAL = xmaterial);
	SET xfull_pallet_quantity = (SELECT NUMERATOR FROM APP_MATERIAL_UOM WHERE MATERIAL = xmaterial AND UOM = xpallet_uom);
	SET xlayers = GetLayers (xmaterial, xfull_pallet_quantity, xbase_uom);
	SET xlayers = COALESCE(xlayers, 1);

	IF xlayers = 0 THEN
		SET xlayers = 1;
	END IF;

	RETURN xlayers;
END

CREATE FUNCTION `GetLayers`(xmaterial VARCHAR (20), xproduction_quantity DECIMAL (22, 3), xproduction_uom VARCHAR (3)) RETURNS int
    READS SQL DATA
BEGIN
	DECLARE	result INT;
	DECLARE	xlayers_uom VARCHAR (3) CHARACTER	SET utf8mb4;
	DECLARE	xpallet_uom VARCHAR (3) CHARACTER	SET utf8mb4;
	DECLARE	xbase_quantity DECIMAL (22, 3);

	SET xbase_quantity = c4j_GetBaseQuantity (xmaterial, xproduction_quantity, xproduction_uom);
	SET xlayers_uom = c4j_GetControlValue ('UOM BASE QTY PER LAYER');
	SET result = (SELECT (xbase_quantity / NUMERATOR * DENOMINATOR) FROM APP_MATERIAL_UOM WHERE MATERIAL = xmaterial AND UOM = xlayers_uom);
	SET result = COALESCE(result, 1);

	IF result = 0 THEN
		SET result = 1;
	END IF;

	RETURN result;
END
